const $=s=>document.querySelector(s);
const icons={home:'M3 10 10 4l7 6v8h-5v-5H8v5H3z',invoice:'M5 2h10v17l-3-2-2 2-2-2-3 2z M8 6h4M8 9h4',users:'M13 18v-2a4 4 0 0 0-8 0v2 M9 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M14 5a3 3 0 0 1 0 6M16 13a4 4 0 0 1 2 4',more:'M4 10h.01M10 10h.01M16 10h.01',bell:'M4 14h12l-2-3V7a4 4 0 0 0-8 0v4zM8 17h4',plus:'M10 4v12M4 10h12',arrow:'M3 10h13M11 5l5 5-5 5',back:'M14 4l-6 6 6 6',lock:'M6 9V6a4 4 0 0 1 8 0v3M4 9h12v9H4z',card:'M2 4h16v12H2zM2 8h16M5 12h3',bank:'M2 7l8-5 8 5zM4 9v7M8 9v7M12 9v7M16 9v7M2 18h16',mail:'M2 4h16v12H2zM2 4l8 7 8-7',message:'M3 3h14v11H8l-5 4z',link:'M8 12l4-4M7 14l-1 1a4 4 0 0 1-5-5l4-4a4 4 0 0 1 5 0M13 6l1-1a4 4 0 0 1 5 5l-4 4a4 4 0 0 1-5 0',chart:'M3 17h14M5 13V9M10 13V4M15 13V7',bag:'M3 6h14v12H3zM7 6V4a3 3 0 0 1 6 0v2',check:'M4 10l4 4 8-9',download:'M10 2v11M6 9l4 4 4-4M3 15v3h14v-3',settings:'M10 6a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 1v3M10 16v3M1 10h3M16 10h3M4 4l2 2M14 14l2 2M4 16l2-2M14 6l2-2'};
function ic(name){return `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${icons[name]||icons.invoice}"/></svg>`}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const clients=[{name:'Olivia Rhye',email:'olivia@example.com',phone:'+1 (212) 555-0142',initial:'OR'},{name:'Phoenix Baker',email:'phoenix@example.com',phone:'+1 (212) 555-0175',initial:'PB'},{name:'Lana Steiner',email:'lana@example.com',phone:'+1 (212) 555-0186',initial:'LS'}];
let state={platform:'ios',merchant:'home',editor:'edit',recipient:'pay',filter:'All',method:'wallet',channel:'Text message',client:0,tax:8,discount:0,due:'2026-10-18',note:'Thank you for supporting a small business.',items:[{name:'Brand identity design',qty:1,rate:1200},{name:'Social media templates',qty:1,rate:300}],saved:false,paid:false};
try{const saved=JSON.parse(localStorage.getItem('invoigo-draft'));if(saved&&Array.isArray(saved.items)&&saved.items.every(i=>typeof i.name==='string'&&Number.isFinite(i.qty)&&i.qty>0&&Number.isFinite(i.rate)&&i.rate>=0)&&Number.isFinite(saved.tax)&&Number.isFinite(saved.discount)&&clients[saved.client])Object.assign(state,saved)}catch{}
function totals(){const subtotal=state.items.reduce((s,i)=>s+i.qty*i.rate,0),discount=Math.min(state.discount,subtotal),tax=Math.round((subtotal-discount)*state.tax)/100;return {subtotal,discount,tax,total:Math.round((subtotal-discount+tax)*100)/100}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function persist(){const {items,tax,discount,due,note,client}=state;try{localStorage.setItem('invoigo-draft',JSON.stringify({items,tax,discount,due,note,client}));state.saved=true;toast('Draft saved on this device')}catch{toast('Storage unavailable. Keep this page open to retain your draft.')}}
function nav(active){return `<nav class="bottomnav" aria-label="App navigation">${[['home','Home'],['invoice','Invoices'],['users','Clients'],['more','More']].map(([key,label])=>`<button class="${active===key?'active':''}" data-action="nav" data-value="${key}" aria-label="${label}" ${active===key?'aria-current="page"':''}>${ic(key)}${label}</button>`).join('')}</nav>`}
function bar(title,back,other=''){return `<div class="bar"><button class="icon-btn" data-action="${back}" aria-label="Back">${ic('back')}</button><b>${title}</b>${other||'<span style="width:40px"></span>'}</div>`}
function rows(){return [{name:clients[state.client].name,initial:clients[state.client].initial,amount:totals().total,status:state.paid?'Paid':'Viewed',id:'1042',sub:state.paid?'Paid just now':'Due '+new Date(state.due+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})},{name:'Phoenix Baker',initial:'PB',amount:850,status:'Overdue',id:'1041',sub:'3 days overdue'},{name:'Lana Steiner',initial:'LS',amount:2400,status:'Paid',id:'1040',sub:'Paid Oct 2'}]}
function row(r){return `<button class="invoice-row" data-action="detail" data-value="${r.id}"><span class="avatar ${r.initial==='LS'?'green':''}">${r.initial}</span><span class="row-detail"><b>${esc(r.name)}</b><small>#INV-${r.id} · ${r.sub}</small></span><span class="row-amount"><b>${money(r.amount)}</b><span class="tag ${r.status==='Overdue'?'due':r.status==='Viewed'?'viewed':''}">${r.status}</span></span></button>`}
function renderMerchant(){let html='';const view=state.merchant;
if(view==='home'){html=`<div class="screen-pad"><div class="toprow"><div class="business"><span class="avatar green">AS</span>Alex Studio <span style="font-size:10px">⌄</span></div><button class="icon-btn" data-action="notifications" aria-label="Notifications">${ic('bell')}</button></div><p class="greeting">Good morning, Alex</p><h2 class="screen-title">Let’s get you paid.</h2><div class="balance"><div class="balance-label"><span>Collected this month</span><span>October ⌄</span></div><div class="balance-amount">${money(12840+(state.paid?totals().total:0)).slice(1,-3)}<span>${money(12840+(state.paid?totals().total:0)).slice(-3)}</span> <span style="font-size:11px;letter-spacing:0">USD</span></div><div class="growth"><b>↗ 18.6%</b><span>vs. last month</span></div><div class="chart" aria-label="Sample monthly collections trending upward">${[17,26,20,30,25,36,31,37,33,45,41,50].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="months"><span>OCT 1</span><span>OCT 31</span></div></div><div class="metrics"><div class="metric"><small>Outstanding</small><strong>${money(state.paid?4220:4220+totals().total)}</strong></div><div class="metric"><small><i></i> Overdue · 1 invoice</small><strong>$850.00</strong></div></div><button class="primary" data-action="new">${ic('plus')} Create invoice</button><div class="section-head">Recent invoices<button class="text-btn" data-action="nav" data-value="invoice">View all</button></div>${rows().slice(0,2).map(row).join('')}</div>${nav('home')}`}
else if(view==='invoice'){html=`<div class="screen-pad"><div class="toprow"><h2 class="screen-title" style="margin:10px 0">Invoices</h2><button class="icon-btn" data-action="new" aria-label="Create invoice">${ic('plus')}</button></div><input id="invoice-search" aria-label="Search invoices" placeholder="Search client or invoice number"><div class="chips">${['All','Viewed','Overdue','Paid','Draft'].map(f=>`<button data-action="filter" data-value="${f}" class="${state.filter===f?'active':''}">${f}</button>`).join('')}</div><div id="invoice-results">${invoiceResults('')}</div></div>${nav('invoice')}`}
else if(view==='users'){html=`<div class="screen-pad"><h2 class="screen-title" style="margin-top:14px">Your clients</h2><p class="sub">Good relationships. All in one place.</p>${clients.map((c,i)=>`<button class="invoice-row" data-action="client-detail" data-value="${i}"><span class="avatar">${c.initial}</span><span class="row-detail"><b>${c.name}</b><small>${c.email}</small></span>↗</button>`).join('')}<div class="notice">Saved details are ready whenever you create an invoice.</div></div>${nav('users')}`}
else if(view==='more'){html=`<div class="screen-pad"><h2 class="screen-title" style="margin-top:14px">Room to grow.</h2><p class="sub">The rest of your business, together.</p>${[['estimates','invoice','Estimates'],['expenses','bag','Expenses'],['reports','chart','Reports'],['items','invoice','Items & services'],['settings','settings','Business settings']].map(([value,icon,label])=>`<button class="menu-row" data-action="nav" data-value="${value}">${ic(icon)}${label}<span>›</span></button>`).join('')}<div class="notice"><b>Your business. Beautifully presented.</b><br>One consistent look, from estimate to receipt.</div></div>${nav('more')}`}
else if(view==='detail'){const r=rows().find(r=>r.id===state.detail)||rows()[0];html=bar('Invoice #'+r.id,'back-home')+`<div class="screen-pad"><span class="tag ${r.status==='Overdue'?'due':''}">${r.status}</span><h2 class="screen-title" style="margin:18px 0 8px">${money(r.amount)}</h2><p class="sub">${r.name} · ${r.sub}</p><div class="timeline"><p>Invoice created<small>Alex Studio · Oct 4</small></p><p>Shared by email<small>Demo activity</small></p><p>${r.status==='Paid'?'Payment received':r.status==='Overdue'?'Payment overdue':'Opened by client'}<small>${r.status==='Paid'?'Receipt available':'Awaiting payment'}</small></p></div><button class="primary" data-action="${r.id==='1042'?'share-current':'reminder'}">${r.status==='Paid'?'View receipt':'Share invoice'}</button>${r.id==='1042'?'<button class="secondary" data-action="edit-current">Edit invoice</button>':''}</div>${nav('invoice')}`}
else if(view==='client-detail'){const c=clients[state.clientDetail||0];html=bar('Client details','back-clients')+`<div class="screen-pad"><span class="avatar green" style="width:58px;height:58px">${c.initial}</span><h2 class="screen-title" style="margin-top:20px">${c.name}</h2><p>${c.email}</p><p>${c.phone}</p><div class="notice">Billing currency · USD<br>Default terms · Due in 14 days</div><button class="primary" data-action="invoice-client" data-value="${state.clientDetail||0}">Create invoice for ${c.name.split(' ')[0]}</button></div>${nav('users')}`}
else if(view==='notifications'){html=bar('Activity','back-home')+`<div class="screen-pad"><div class="timeline"><p>${clients[state.client].name} ${state.paid?'paid':'viewed'} your invoice<small>#1042 · Demo activity</small></p><p>Lana paid $2,400.00<small>#1040 · Oct 2</small></p><p>One invoice needs a nudge<small>#1041 · 3 days overdue</small></p></div><button class="primary" data-action="filter-overdue">Review overdue invoice</button></div>${nav('home')}`}
else if(view==='estimates'){html=bar('Estimates','back-more')+`<div class="screen-pad"><h2 class="screen-title" style="margin-top:18px">Start with a yes.</h2><div class="paper"><span class="tag">Accepted · sample</span><h2>$1,500.00</h2><p>Olivia Rhye<br>Brand identity + social templates</p><p>Estimate #EST-0086</p></div><div class="notice">Turn approved work into an invoice. Client and line items carry over.</div><button class="primary" data-action="convert">Convert to invoice</button></div>${nav('more')}`}
else if(view==='expenses'){html=bar('Expenses','back-more')+`<div class="screen-pad"><p class="greeting" style="margin-top:18px">October expenses · sample</p><h2 class="report-amount">$468.50</h2>${[{name:'Design software',initial:'Ds',amount:89,status:'Paid',id:'E03',sub:'Software · Oct 3'},{name:'Print supplies',initial:'Ps',amount:129.50,status:'Paid',id:'E02',sub:'Materials · Oct 2'},{name:'Studio rent',initial:'Sr',amount:250,status:'Paid',id:'E01',sub:'Office · Oct 1'}].map(r=>`<div class="invoice-row"><span class="avatar green">${r.initial}</span><span class="row-detail"><b>${r.name}</b><small>${r.sub}</small></span><b>${money(r.amount)}</b></div>`).join('')}<label class="attachment-label">Preview a receipt attachment<input type="file" id="receipt-file" accept="image/*,.pdf"></label><p class="sub" id="receipt-status">File stays on your device in this prototype.</p></div>${nav('more')}`}
else if(view==='reports'){html=bar('Business report','back-more')+`<div class="screen-pad"><div class="chips"><button class="active">October 2026</button></div><p class="greeting">Collected revenue · sample</p><h2 class="report-amount">$12,840.00</h2><div class="balance"><div class="balance-label">Your month in numbers</div><div class="chart">${[20,35,27,44,36,50,42,49].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div><div class="totals"><div class="total-row"><span>Revenue</span><b>$12,840.00</b></div><div class="total-row"><span>Expenses</span><b>$468.50</b></div><div class="total-row total"><span>Net income</span><b>$12,371.50</b></div></div><button class="primary" data-action="export">${ic('download')} Export report CSV</button></div>${nav('more')}`}
else if(view==='items'){html=bar('Items & services','back-more')+`<div class="screen-pad"><p class="sub" style="margin-top:20px">Tap a saved service to add it to your invoice.</p>${[{name:'Brand identity design',rate:1200},{name:'Social media templates',rate:300},{name:'Design consultation',rate:150}].map((i,n)=>`<button class="menu-row" data-action="catalog-item" data-value="${n}"><span>${i.name}<small style="display:block;margin-top:6px">${money(i.rate)} / project</small></span><span>＋</span></button>`).join('')}</div>${nav('more')}`}
else if(view==='settings'){html=bar('Business settings','back-more')+`<div class="screen-pad"><div class="business" style="margin:20px 0"><span class="avatar green">AS</span>Alex Studio</div><div class="notice">Design preview · These settings describe the production experience.</div>${['Business profile & logo','Invoice templates & colors','Bank details & payment methods','Tax, currency & default terms','Reminders & notifications','Signature & attachments','Subscription & support'].map(s=>`<details style="padding:14px 0;border-bottom:1px solid var(--border)"><summary style="cursor:pointer;font-size:11px">${s}</summary><p class="sub" style="margin:12px 0 0">Account-backed configuration is included in the implementation handoff. See Design & feature notes for integration requirements.</p></details>`).join('')}</div>${nav('more')}`}
$('#merchant-screen').innerHTML=html}
function invoiceResults(search){let list=rows().filter(r=>(state.filter==='All'||r.status===state.filter)&&(`${r.name} ${r.id}`.toLowerCase().includes(search.toLowerCase())));if(state.filter==='Draft')return state.saved?`<button class="invoice-row" data-action="edit-current"><span class="row-detail"><b>Invoice #1042</b><small>Saved on this device</small></span><b>${money(totals().total)}</b></button>`:'<p class="empty">No saved drafts yet.</p>';return list.length?list.map(row).join(''):'<p class="empty">No invoices match your search.</p>'}
function summary(){const t=totals();return `<div class="total-row"><span>Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="total-row"><span>Discount</span><span>−${money(t.discount)}</span></div>`:''}<div class="total-row"><span>Tax (${state.tax}%)</span><span>${money(t.tax)}</span></div><div class="total-row total"><span>Total <span style="font-size:9px;font-weight:400">USD</span></span><span>${money(t.total)}</span></div>`}
function renderEditor(){const c=clients[state.client];let html='';if(state.editor==='edit'){html=bar('New invoice','editor-reset','<button class="text-btn" data-action="save">Save</button>')+`<div class="progress"><span class="on"></span><span></span><span></span></div><div class="screen-pad"><h2 class="editor-heading">Make it yours.</h2><p class="sub">Invoice #INV-1042</p><label class="label">BILL TO</label><button class="client-select" data-action="choose-client"><span class="avatar">${c.initial}</span><span class="row-detail"><b>${c.name}</b><small>${c.email}</small></span><span>⌄</span></button><div class="two-fields"><label><span class="label">Invoice date</span><input type="date" value="2026-10-04" aria-label="Invoice date" readonly></label><label><span class="label">Due date</span><input type="date" id="due-date" value="${esc(state.due)}" min="2026-10-04" aria-label="Due date"></label></div><div class="section-head" style="margin-top:22px">Items <span style="font-size:9px;color:var(--muted);font-weight:400">${state.items.length} items</span></div>${state.items.map((i,n)=>`<button class="item" style="width:100%;border:0;border-bottom:1px solid var(--border);background:none;text-align:left" data-action="edit-item" data-value="${n}"><span class="item-icon">${ic('invoice')}</span><span class="row-detail"><b>${esc(i.name)}</b><small>${i.qty} × ${money(i.rate)}</small></span><strong>${money(i.qty*i.rate)}</strong></button>`).join('')}<button class="add-item" data-action="add-item">＋ &nbsp; Add an item</button><div class="totals"><div class="total-row"><span>Subtotal</span><span>${money(totals().subtotal)}</span></div><div class="total-row"><button data-action="adjustments">Tax (${state.tax}%)</button><span>${money(totals().tax)}</span></div><div class="total-row"><button data-action="adjustments">${state.discount?'Discount':'＋ Add a discount'}</button><span>${state.discount?'−'+money(totals().discount):''}</span></div><div class="total-row total"><span>Total <small style="font-size:9px;font-weight:400">USD</small></span><span>${money(totals().total)}</span></div></div><button class="text-btn" data-action="notes">Add a note or attachment</button></div><div class="editor-bottom"><button class="primary" data-action="review">Review invoice ${ic('arrow')}</button><p class="helper">Your details. Looking professional.</p></div>`}
else if(state.editor==='clients'){html=bar('Choose a client','edit-current')+`<div class="screen-pad">${clients.map((c,i)=>`<button class="invoice-row" data-action="select-client" data-value="${i}"><span class="avatar">${c.initial}</span><span class="row-detail"><b>${c.name}</b><small>${c.email}</small></span>›</button>`).join('')}</div>`}
else if(state.editor==='item'){const i=state.editIndex==null?{name:'',qty:1,rate:''}:state.items[state.editIndex];html=bar(state.editIndex==null?'Add an item':'Edit item','edit-current')+`<form id="item-form" class="screen-pad"><label class="label" for="item-name">Item or service</label><input id="item-name" required maxlength="70" value="${esc(i.name)}" placeholder="e.g. Design consultation"><div class="inline-inputs"><label><span class="label">Quantity</span><input id="item-qty" type="number" min="0.01" step="0.01" max="100000" required value="${i.qty}"></label><label><span class="label">Rate (USD)</span><input id="item-rate" type="number" min="0" step="0.01" max="1000000" required value="${i.rate}"></label></div><p class="sub" style="margin-top:15px">Tax and discounts apply to the invoice total.</p><button class="primary" type="submit">${state.editIndex==null?'Add to invoice':'Save item'}</button>${state.editIndex!=null?'<button class="secondary" type="button" data-action="remove-item">Remove item</button>':''}</form>`}
else if(state.editor==='adjustments'){html=bar('Tax & discount','edit-current')+`<form id="adjust-form" class="screen-pad"><label class="label">Tax rate (%)</label><input id="tax-input" type="number" min="0" max="100" step="0.01" required value="${state.tax}"><label class="label">Discount (USD)</label><input id="discount-input" type="number" min="0" max="${totals().subtotal}" step="0.01" required value="${state.discount}"><p class="sub" style="margin-top:15px">Discount is applied before tax.</p><button class="primary">Apply changes</button></form>`}
else if(state.editor==='notes'){html=bar('The finishing touches','edit-current')+`<div class="screen-pad"><label class="label" for="invoice-note">Note to your client</label><textarea id="invoice-note" maxlength="500">${esc(state.note)}</textarea><label class="attachment-label">Attachment preview<input id="invoice-file" type="file" accept="image/*,.pdf"></label><p class="sub" id="attachment-status">Local preview only. Production upload and signature capture are specified in the handoff.</p><button class="primary" data-action="save-note">Save note</button></div>`}
else if(state.editor==='review'){html=bar('Review invoice','edit-current','<button class="text-btn" data-action="print">PDF</button>')+`<div class="progress"><span class="on"></span><span class="on"></span><span></span></div><div class="screen-pad"><div class="paper"><b>ALEX STUDIO</b><h2>Invoice.</h2><p>#INV-1042<br>Issued Oct 4, 2026 · Due ${esc(state.due)}</p><hr style="border:0;border-top:1px solid var(--border)"><p>Bill to<br><b>${c.name}</b><br>${c.email}</p>${state.items.map(i=>`<div class="total-row"><span>${esc(i.name)}<br><small>${i.qty} × ${money(i.rate)}</small></span><b>${money(i.qty*i.rate)}</b></div>`).join('')}${summary()}<p>${esc(state.note)}</p></div></div><div class="editor-bottom"><button class="primary" data-action="open-share">Ready to send ${ic('arrow')}</button><p class="helper">Online payment link included</p></div>`}
else if(state.editor==='share'){html=bar('Send invoice','review')+`<div class="progress"><span class="on"></span><span class="on"></span><span class="on"></span></div><div class="screen-pad"><h2 class="editor-heading">A good day to get paid.</h2><p class="sub">${money(totals().total)} · Invoice #1042</p>${[['Text message','message',c.phone],['Email','mail',c.email],['Payment link','link','Share wherever you work']].map(([name,icon,sub])=>`<button class="pay-option ${state.channel===name?'active':''}" data-action="channel" data-value="${name}">${ic(icon)}<span class="row-detail"><b>${name}</b><small>${sub}</small></span><span class="radio"></span></button>`).join('')}<div class="message-preview">Hi ${c.name.split(' ')[0]}, thanks for working with Alex Studio. Your invoice for <b>${money(totals().total)}</b> is ready.<br><br>View your invoice and pay securely:<br><u>invoingo.example/pay/INV-1042</u></div><p class="sub">Demo preview. No message will be sent. A production link opens secure checkout from text, email, or the app.</p></div><div class="editor-bottom"><button class="primary" data-action="send-demo">${state.channel==='Payment link'?'Copy demo link':'Preview '+state.channel.toLowerCase()} ${ic('arrow')}</button></div>`}
else if(state.editor==='sent'){html=bar('Share preview','open-share')+`<div class="screen-pad center"><div class="success-mark">${ic('check')}</div><h2 class="success-title">Ready for their inbox.</h2><p class="sub">${state.channel} preview for ${c.name}.<br>No external message was sent.</p><div class="notice">The recipient’s checkout is open in screen 03. Complete a demo payment to see the invoice update.</div><button class="primary" data-action="show-recipient">Try the client experience ${ic('arrow')}</button><button class="secondary" data-action="open-share">Choose another channel</button></div>`}
$('#editor-screen').innerHTML=html}
function renderRecipient(){const t=totals(),wallet=state.platform==='ios'?'Apple Pay':'Google Pay';let html='';if(state.recipient==='success'){html=`<div class="checkout center"><div class="securebar">${ic('lock')} invoingo · demo receipt</div><div class="success-mark">${ic('check')}</div><h2 class="success-title">All paid.<br>All yours.</h2><p class="sub">Thanks, ${clients[state.client].name.split(' ')[0]}.<br>Your demo payment to Alex Studio is complete.</p><div class="receipt-summary" style="text-align:left"><div class="total-row"><span>Invoice</span><b>#INV-1042</b></div><div class="total-row"><span>Payment method</span><b>${state.method==='wallet'?wallet:state.method==='card'?'Card':'Bank transfer'}</b></div><div class="total-row total"><span>Amount paid</span><b>${money(t.total)}</b></div></div><p class="sub">Simulation only. No payment was processed.</p><button class="primary" data-action="download-receipt">${ic('download')} Download demo receipt</button><button class="secondary" data-action="reset-payment">Back to invoice</button><p class="powered">Made simple with <b>invoingo ↗</b></p></div>`}
else if(state.recipient==='message'){html=bar(state.channel==='Email'?'Email preview':'Message preview','recipient-pay')+`<div class="checkout"><div class="center" style="padding-top:20px"><span class="avatar green" style="margin:auto">AS</span><p class="merchant-name" style="margin-top:12px">Alex Studio</p><p class="sub">${state.channel==='Email'?'To: '+clients[state.client].email:'Business message · Demo'}</p></div><div class="message-preview">Hi ${clients[state.client].name.split(' ')[0]}, your invoice from Alex Studio is ready.<br><br><b>Invoice #1042 · ${money(t.total)}</b><br>Due ${esc(state.due)}<br><br>Thanks for working with us!</div><button class="primary" data-action="recipient-pay">View invoice & pay ${ic('arrow')}</button><p class="helper">Secure checkout · No account needed</p></div>`}
else{html=`<div class="checkout"><div class="securebar">${ic('lock')} invoingo · secure checkout preview</div><div class="center"><div class="merchant-emblem">as.</div><p class="merchant-name">Alex Studio</p><span class="invoice-meta">Invoice #INV-1042</span><p class="pay-title">Great work. Ready to make it official?</p><h2 class="pay-amount">${money(t.total)}</h2><span class="pay-due">Due ${new Date(state.due+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span></div><div class="receipt-summary">${state.items.map(i=>`<div class="total-row"><span>${esc(i.name)}</span><span>${money(i.qty*i.rate)}</span></div>`).join('')}${t.discount?`<div class="total-row"><span>Discount</span><span>−${money(t.discount)}</span></div>`:''}<div class="total-row"><span>Tax (${state.tax}%)</span><span>${money(t.tax)}</span></div><div class="total-row total"><span>Total due</span><span>${money(t.total)}</span></div></div><p class="pay-label">How would you like to pay?</p>${[['wallet','card',wallet],['card','card','Debit or credit card'],['bank','bank','Bank transfer']].map(([key,icon,label])=>`<button class="pay-option ${state.method===key?'active':''}" data-action="pay-method" data-value="${key}" aria-pressed="${state.method===key}">${ic(icon)}<span>${label}</span><span class="radio"></span></button>`).join('')}<button class="primary pay-cta" data-action="pay-demo">${ic('lock')} Pay ${money(t.total)}</button><p class="helper">Demo payment · No charge will be made</p><p class="powered">Made simple with <b>invoingo ↗</b></p></div>`}
$('#recipient-screen').innerHTML=html}
function render(){renderMerchant();renderEditor();renderRecipient()}
function setEditor(view){state.editor=view;renderEditor();$('#editor-screen').scrollTop=0}
function focusDevice(id){if(innerWidth<1001)$('#'+id).scrollIntoView({behavior:'smooth',block:'start'})}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
document.addEventListener('click',async e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.platform){state.platform=btn.dataset.platform;document.body.classList.toggle('android',state.platform==='android');document.querySelectorAll('[data-platform]').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn))});renderRecipient();return}const a=btn.dataset.action,v=btn.dataset.value;if(!a)return;
if(a==='nav'){state.merchant=v;renderMerchant()}if(a==='back-home'){state.merchant='home';renderMerchant()}if(a==='back-more'){state.merchant='more';renderMerchant()}if(a==='back-clients'){state.merchant='users';renderMerchant()}if(a==='notifications'){state.merchant='notifications';renderMerchant()}if(a==='filter'){state.filter=v;renderMerchant()}if(a==='filter-overdue'){state.filter='Overdue';state.merchant='invoice';renderMerchant()}if(a==='detail'){state.detail=v;state.merchant='detail';renderMerchant()}if(a==='client-detail'){state.clientDetail=Number(v);state.merchant='client-detail';renderMerchant()}
if(['new','edit-current','editor-reset'].includes(a)){setEditor('edit');focusDevice('editor');if(a==='new')toast('Invoice editor is ready. Your draft is preserved.')}
if(a==='invoice-client'){state.client=Number(v);state.paid=false;state.recipient='pay';state.editor='edit';render();focusDevice('editor')}
if(a==='save')persist();if(a==='choose-client')setEditor('clients');if(a==='select-client'){state.client=Number(v);setEditor('edit');renderRecipient();renderMerchant()}
if(a==='add-item'){state.editIndex=null;setEditor('item')}if(a==='edit-item'){state.editIndex=Number(v);setEditor('item')}if(a==='remove-item'){state.items.splice(state.editIndex,1);state.paid=false;state.recipient='pay';setEditor('edit');renderRecipient();renderMerchant()}if(a==='adjustments')setEditor('adjustments');if(a==='notes')setEditor('notes');if(a==='save-note'){state.note=$('#invoice-note').value;setEditor('edit')}
if(a==='review'){if(!state.items.length){toast('Add at least one item before reviewing.');return}if(!state.due||state.due<'2026-10-04'){toast('Choose a due date on or after the invoice date.');return}setEditor('review')}if(a==='print')window.print();if(a==='open-share')setEditor('share');if(a==='channel'){state.channel=v;renderEditor()}
if(a==='send-demo'){state.recipient=state.channel==='Payment link'?'pay':'message';if(state.channel==='Payment link'){try{await navigator.clipboard.writeText(location.origin+'/?demo=payment#recipient');toast('Local demo checkout link copied')}catch{toast('Clipboard unavailable. Use the checkout preview in screen 03.')}}setEditor('sent');renderRecipient()}
if(a==='show-recipient')focusDevice('recipient');if(a==='recipient-pay'){state.recipient='pay';renderRecipient()}if(a==='pay-method'){state.method=v;renderRecipient()}
if(a==='pay-demo'){if(totals().total<=0){toast('The invoice needs a positive balance to simulate payment.');return}state.paid=true;state.recipient='success';renderRecipient();renderMerchant();toast('Demo payment complete. Invoice marked paid in this preview.')}
if(a==='reset-payment'){state.paid=false;state.recipient='pay';renderRecipient();renderMerchant()}if(a==='download-receipt')download('Invoingo-demo-receipt-1042.txt',`DEMO RECEIPT — No real payment\nAlex Studio\nInvoice INV-1042\nClient: ${clients[state.client].name}\nAmount: ${money(totals().total)}\nStatus: Simulated payment complete`,'text/plain');
if(a==='export')download('invoingo-october-demo.csv','Sample data,October 2026\nMetric,USD\nCollected revenue,12840\nExpenses,468.50\nNet income,12371.50','text/csv');
if(a==='convert'){state.items=[{name:'Brand identity design',qty:1,rate:1200},{name:'Social media templates',qty:1,rate:300}];state.client=0;state.paid=false;state.recipient='pay';state.editor='edit';render();focusDevice('editor');toast('Sample estimate copied into the invoice editor')}
if(a==='catalog-item'){const items=[{name:'Brand identity design',qty:1,rate:1200},{name:'Social media templates',qty:1,rate:300},{name:'Design consultation',qty:1,rate:150}];state.items.push(items[Number(v)]);state.paid=false;state.recipient='pay';state.editor='edit';render();toast('Saved service added to invoice')}
if(a==='share-current'){if(state.paid){state.recipient='success';renderRecipient();focusDevice('recipient')}else{setEditor('share');focusDevice('editor')}}if(a==='reminder')toast('This sample invoice is read-only. Try sharing invoice #1042.');
});
document.addEventListener('input',e=>{if(e.target.id==='invoice-search')$('#invoice-results').innerHTML=invoiceResults(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='due-date'){if(e.target.value&&e.target.value>='2026-10-04'){state.due=e.target.value;renderRecipient()}else{toast('Due date must be on or after Oct 4, 2026.');e.target.value=state.due}}if(e.target.id==='invoice-file')$('#attachment-status').textContent=e.target.files[0]?'Selected: '+e.target.files[0].name+' (local preview only)':'No attachment selected';if(e.target.id==='receipt-file')$('#receipt-status').textContent=e.target.files[0]?'Selected: '+e.target.files[0].name+' (local preview only)':'No receipt selected'});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='item-form'){const item={name:$('#item-name').value.trim(),qty:Number($('#item-qty').value),rate:Number($('#item-rate').value)};if(!item.name){toast('Enter an item name.');return}if(state.editIndex==null)state.items.push(item);else state.items[state.editIndex]=item;state.paid=false;state.recipient='pay';setEditor('edit');renderRecipient();renderMerchant()}if(e.target.id==='adjust-form'){state.tax=Number($('#tax-input').value);state.discount=Number($('#discount-input').value);state.paid=false;state.recipient='pay';setEditor('edit');renderRecipient();renderMerchant()}});
render();if(new URLSearchParams(location.search).get('demo')==='payment')setTimeout(()=>focusDevice('recipient'),100);

